      <section class="content-frame"><div class="section-heading"><div><p>编辑精选</p><h2>{{ currentTitle }}</h2></div><span>按发布时间排序</span></div><ArticleList :gameCode="currentGameCode" :contentType="currentContentType" @update:total="t => total = t" /></section>
    </main>
  </div>
</template>
<script setup>
import { ref, onMounted, computed } from 'vue'
import { useRouter } from 'vue-router'
import ArticleList from '../components/ArticleList.vue'
import { useCategoryStore } from '../stores/category'
import { useUserStore } from '../stores/user'
const router=useRouter(),categoryStore=useCategoryStore(),userStore=useUserStore();const isLogin=computed(()=>userStore.isLoggedIn);const currentGameCode=ref(null),total=ref(0),currentContentType=ref(null)
const CAT_COLORS=['#d92d27'];const contentTypes=[{code:'announcement',name:'公告'},{code:'patch_notes',name:'版本更新'},{code:'event',name:'活动'},{code:'new_content',name:'新内容'},{code:'guide',name:'攻略'},{code:'esports',name:'赛事'}]
const tabs=computed(()=>[{id:null,name:'全部'},...categoryStore.items.map(c=>({id:c.code,name:c.nameZh,dotColor:CAT_COLORS[0]}))]);const currentTitle=computed(()=>currentGameCode.value===null?'最新资讯':categoryStore.getName(currentGameCode.value));const selectCategory=id=>{currentGameCode.value=id};onMounted(()=>categoryStore.fetchCategories())
</script>
